/**
 * frontend/src/auth_service.js - Version corrigée
 * Gestion de l'authentification et JWT tokens
 */

import api from './api_service';

const AUTH_TOKEN_KEY = 'access_token';
const REFRESH_TOKEN_KEY = 'refresh_token';

class AuthService {
  /**
   * Login user
   */
  async login(username, password) {
    try {
      const response = await api.post('/auth/login/', { username, password });

      // Fallback si user n'est pas renvoyé
      const { access, refresh, user = {} } = response.data;

      if (!access) {
        return { success: false, error: 'No access token received' };
      }

      // Store tokens
      localStorage.setItem(AUTH_TOKEN_KEY, access);
      if (refresh) localStorage.setItem(REFRESH_TOKEN_KEY, refresh);

      // Store user info (vide si non fourni)
      localStorage.setItem('user', JSON.stringify(user));

      this.setAuthHeader(access);

      return { success: true, user };
    } catch (error) {
      console.error('Login error:', error);
      return {
        success: false,
        error:
          error.response?.data?.error ||
          error.response?.data?.detail ||
          'Login failed'
      };
    }
  }

  /**
   * Register new user
   */
  async register(username, email, password, passwordConfirm, firstName = '') {
    try {
      const response = await api.post('/auth/register/', {
        username,
        email,
        password,
        password_confirm: passwordConfirm,
        first_name: firstName
      });

      const { access, refresh, user = {} } = response.data;

      if (!access) {
        return { success: false, error: 'No access token received' };
      }

      localStorage.setItem(AUTH_TOKEN_KEY, access);
      if (refresh) localStorage.setItem(REFRESH_TOKEN_KEY, refresh);
      localStorage.setItem('user', JSON.stringify(user));

      this.setAuthHeader(access);

      return { success: true, user };
    } catch (error) {
      console.error('Registration error:', error);
      return {
        success: false,
        error:
          error.response?.data?.error ||
          error.response?.data?.detail ||
          'Registration failed'
      };
    }
  }

  /**
   * Logout user
   */
  async logout() {
    try {
      const refreshToken = localStorage.getItem(REFRESH_TOKEN_KEY);

      if (refreshToken) {
        await api.post('/auth/logout/', { refresh: refreshToken });
      }

      this.clearAuth();
      return { success: true };
    } catch (error) {
      console.error('Logout error:', error);
      this.clearAuth();
      return { success: true };
    }
  }

  /**
   * Refresh access token
   */
  async refreshToken() {
    try {
      const refreshToken = localStorage.getItem(REFRESH_TOKEN_KEY);

      if (!refreshToken) {
        this.clearAuth();
        return { success: false };
      }

      const response = await api.post('/auth/refresh/', { refresh: refreshToken });
      const { access } = response.data;

      if (!access) {
        this.clearAuth();
        return { success: false };
      }

      localStorage.setItem(AUTH_TOKEN_KEY, access);
      this.setAuthHeader(access);

      return { success: true, access };
    } catch (error) {
      console.error('Token refresh error:', error);
      this.clearAuth();
      return { success: false };
    }
  }

  /**
   * Get current user
   */
  async getCurrentUser() {
    try {
      const response = await api.get('/auth/me/');
      return response.data;
    } catch (error) {
      console.error('Get user error:', error);
      return null;
    }
  }

  /**
   * Set auth header for API requests
   */
  setAuthHeader(token) {
    if (token) {
      api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
    }
  }

  getToken() {
    return localStorage.getItem(AUTH_TOKEN_KEY);
  }

  isAuthenticated() {
    return !!localStorage.getItem(AUTH_TOKEN_KEY);
  }

  getUser() {
    const user = localStorage.getItem('user');
    return user ? JSON.parse(user) : null;
  }

  clearAuth() {
    localStorage.removeItem(AUTH_TOKEN_KEY);
    localStorage.removeItem(REFRESH_TOKEN_KEY);
    localStorage.removeItem('user');
    delete api.defaults.headers.common['Authorization'];
  }

  initialize() {
    const token = this.getToken();
    if (token) {
      this.setAuthHeader(token);
    }
  }
}

export default new AuthService();
